67	    /// Build and send a request with DPoP headers, retrying once on `use_dpop_nonce`.
68	    async fn execute_with_retry<B: Serialize + Sync>(
69	        &self,
70	        method: reqwest::Method,
71	        url: &str,
72	        body: Option<&B>,
73	    ) -> Result<Response, OAuthError> {
74	        // Lazy refresh before reading the access token.
75	        self.maybe_refresh_token().await?;
76	
77	        let nonce_opt = {
78	            let s = self.session.lock().unwrap();
79	            s.dpop_nonce.clone()
80	        };
81	
82	        let resp = self
83	            .send_with_dpop(&method, url, body, nonce_opt.as_deref())
84	            .await?;
85	
86	        // On use_dpop_nonce, extract the server nonce from the DPoP-Nonce header,
87	        // update session, and retry once.
88	        if resp.status().as_u16() == 400 {
89	            // Extract nonce header BEFORE consuming the body.
90	            let maybe_nonce = resp
91	                .headers()
92	                .get("DPoP-Nonce")
93	                .and_then(|v| v.to_str().ok())
94	                .map(str::to_string);
95	
96	            // Now consume the body to check the error type.
97	            let error_body = resp.text().await.unwrap_or_default();
98	
99	            // Parse the error response to check for use_dpop_nonce.
100	            let is_use_dpop_nonce = {
101	                serde_json::from_str::<serde_json::Value>(&error_body)
102	                    .ok()
103	                    .and_then(|v| v.get("error")?.as_str().map(|e| e == "use_dpop_nonce"))
104	                    .unwrap_or(false)
105	            };
106	
107	            if is_use_dpop_nonce {
108	                if let Some(fresh_nonce) = maybe_nonce {
109	                    {
110	                        let mut s = self.session.lock().unwrap();
111	                        s.dpop_nonce = Some(fresh_nonce.clone());
112	                    }
113	                    tracing::debug!(nonce = %fresh_nonce, "retrying request with server DPoP nonce");
114	                    // Do NOT re-check expiry on the retry — avoid double-refresh.
115	                    return self
116	                        .send_with_dpop(&method, url, body, Some(&fresh_nonce))
117	                        .await;
118	                } else {
119	                    // use_dpop_nonce but no nonce header — this is an error.
120	                    tracing::error!("use_dpop_nonce response missing DPoP-Nonce header");
