134	    /// Send a single request with `Authorization: DPoP` and `DPoP: {proof}` headers.
135	    async fn send_with_dpop<B: Serialize + Sync>(
136	        &self,
137	        method: &reqwest::Method,
138	        url: &str,
139	        body: Option<&B>,
140	        nonce: Option<&str>,
141	    ) -> Result<Response, OAuthError> {
