149	            .dpop
150	            .make_proof(method.as_str(), url, nonce, Some(&ath))?;
151	
152	        let mut builder = match method {
153	            m if *m == reqwest::Method::GET => self.inner.get(url),
154	            m if *m == reqwest::Method::POST => self.inner.post(url),
155	            _ => return Err(OAuthError::NotAuthenticated),
156	        };
157	
158	        builder = builder
159	            .header("Authorization", format!("DPoP {access_token}"))
160	            .header("DPoP", &proof);
161	
162	        if let (Some(b), m) = (body, method) {
163	            if *m == reqwest::Method::POST {
