304	    /// Deserialize a 200 token response and update session + Keychain.
305	    async fn apply_token_response(&self, resp: Response) -> Result<(), OAuthError> {
306	        // Capture the DPoP-Nonce header before consuming the response body.
307	        let new_nonce = resp
308	            .headers()
309	            .get("DPoP-Nonce")
310	            .and_then(|v| v.to_str().ok())
311	            .map(str::to_string);
312	
313	        let token_resp: crate::http::TokenResponse = resp.json().await.map_err(|e| {
314	            tracing::error!(error = %e, "token refresh response deserialization failed");
315	            OAuthError::TokenRefreshFailed
316	        })?;
317	
318	        let expires_at = std::time::SystemTime::now()
319	            .duration_since(std::time::UNIX_EPOCH)
320	            .map_err(|_| OAuthError::TokenRefreshFailed)?
321	            .as_secs()
322	            + token_resp.expires_in;
323	
324	        crate::keychain::store_oauth_tokens(&token_resp.access_token, &token_resp.refresh_token)
325	            .map_err(|_| OAuthError::KeychainError)?;
326	
327	        let mut s = self.session.lock().unwrap();
328	        s.access_token = token_resp.access_token;
329	        s.refresh_token = token_resp.refresh_token;
330	        s.expires_at = expires_at;
331	        s.dpop_nonce = new_nonce;
332	
333	        tracing::info!("access token refreshed");
334	        Ok(())
335	    }
