// pattern: Imperative Shell
//
// Gathers: bearer session (access_jwt, refresh_jwt), request params
// Processes: header attachment (Authorization: Bearer) → (lazy refresh) → send
// Returns: reqwest::Response or BearerError
//
// The destination PDS in an outbound migration authenticates every call with the plain
// bearer session that `com.atproto.server.createAccount` returns — NOT the DPoP/OAuth
// tokens the wallet's `OAuthClient` speaks. This client carries `Authorization: Bearer`
// and supports raw-byte bodies (CAR imports, blob uploads) that `OAuthClient` (JSON-only)
// cannot.

use std::sync::{Arc, Mutex};

use reqwest::{Client, Response};
use serde::Serialize;

/// A plain ATProto bearer session (access + refresh JWTs), as returned by
/// `com.atproto.server.createAccount` / `refreshSession`.
#[derive(Debug, Clone)]
pub struct BearerSession {
    pub access_jwt: String,
    pub refresh_jwt: String,
}

/// Bearer-authenticated HTTP client for a single PDS base URL.
pub struct BearerClient {
    inner: Client,
    session: Arc<Mutex<BearerSession>>,
    base_url: String,
}

impl BearerClient {
    /// Construct from an existing bearer session and the PDS base URL.
    pub fn new(session: Arc<Mutex<BearerSession>>, base_url: String) -> Self {
        Self {
            inner: Client::new(),
            session,
            base_url,
        }
    }

    fn url(&self, path: &str) -> String {
        format!("{}/{}", self.base_url, path.trim_start_matches('/'))
    }

    fn access_jwt(&self) -> String {
        self.session.lock().unwrap().access_jwt.clone()
    }

    /// GET `{base_url}/{path}` with `Authorization: Bearer`.
    pub async fn get(&self, path: &str) -> reqwest::Result<Response> {
        // STUB (RED): deliberately omits the bearer header so the header test fails first.
        self.inner.get(self.url(path)).send().await
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use httpmock::prelude::*;

    fn session(access: &str) -> Arc<Mutex<BearerSession>> {
        Arc::new(Mutex::new(BearerSession {
            access_jwt: access.to_string(),
            refresh_jwt: "refresh".to_string(),
        }))
    }

    #[tokio::test]
    async fn get_attaches_bearer_authorization_header() {
        let server = MockServer::start();
        server.mock(|when, then| {
            when.method(GET)
                .path("/xrpc/com.atproto.server.checkAccountStatus")
                .header("Authorization", "Bearer dest_access_jwt");
            then.status(200).json_body(serde_json::json!({ "activated": false }));
        });

        let client = BearerClient::new(session("dest_access_jwt"), server.base_url());
        let resp = client
            .get("/xrpc/com.atproto.server.checkAccountStatus")
            .await
            .expect("request sends");

        assert_eq!(
            resp.status().as_u16(),
            200,
            "GET must carry Authorization: Bearer <accessJwt> so the mock matches"
        );
    }
}

