// pattern: Imperative Shell
//
// Gathers: bearer session (access_jwt, refresh_jwt), request params
// Processes: lazy refresh → header attachment (Authorization: Bearer) → send
// Returns: reqwest::Response or BearerError
//
// The destination PDS in an outbound migration authenticates every call with the plain
// bearer session that `com.atproto.server.createAccount` returns — NOT the DPoP/OAuth
// tokens the wallet's `OAuthClient` speaks. This client carries `Authorization: Bearer`
// and supports raw-byte bodies (CAR imports, blob uploads) that `OAuthClient` (JSON-only)
// cannot.

use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

use base64::Engine;
use reqwest::{Client, Response};
use serde::{Deserialize, Serialize};

/// A plain ATProto bearer session (access + refresh JWTs), as returned by
/// `com.atproto.server.createAccount` / `refreshSession`.
#[derive(Debug, Clone)]
pub struct BearerSession {
    pub access_jwt: String,
    pub refresh_jwt: String,
}

/// Errors from the bearer client's own operations (currently only session refresh).
#[derive(Debug, thiserror::Error)]
pub enum BearerError {
    #[error("network error: {0}")]
    Network(String),
    #[error("refreshSession failed: HTTP {0}")]
    RefreshFailed(u16),
}

/// Subset of the `com.atproto.server.refreshSession` response the client consumes.
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RefreshResponse {
    access_jwt: String,
    refresh_jwt: String,
}

/// Bearer-authenticated HTTP client for a single PDS base URL.
pub struct BearerClient {
    inner: Client,
    session: Arc<Mutex<BearerSession>>,
    base_url: String,
}

impl BearerClient {
    /// Construct from an existing bearer session and the PDS base URL.
    pub fn new(session: Arc<Mutex<BearerSession>>, base_url: String) -> Self {
        Self {
            inner: Client::new(),
            session,
            base_url,
        }
    }

    fn url(&self, path: &str) -> String {
        format!("{}/{}", self.base_url, path.trim_start_matches('/'))
    }

    fn access_jwt(&self) -> String {
        self.session.lock().unwrap().access_jwt.clone()
    }

    /// GET `{base_url}/{path}` with `Authorization: Bearer`.
    pub async fn get(&self, path: &str) -> reqwest::Result<Response> {
        self.maybe_refresh().await;
        self.inner
            .get(self.url(path))
            .bearer_auth(self.access_jwt())
            .send()
            .await
    }

    /// POST a JSON body to `{base_url}/{path}` with `Authorization: Bearer`.
    pub async fn post_json<B: Serialize + Sync>(
        &self,
        path: &str,
        body: &B,
    ) -> reqwest::Result<Response> {
        self.maybe_refresh().await;
        self.inner
            .post(self.url(path))
            .bearer_auth(self.access_jwt())
            .json(body)
            .send()
            .await
    }

    /// POST raw bytes to `{base_url}/{path}` with `Authorization: Bearer` and an explicit
    /// `Content-Type`. Used for CAR imports (`importRepo`) and blob uploads (`uploadBlob`),
    /// which carry binary bodies rather than JSON.
    pub async fn post_bytes(
        &self,
        path: &str,
        body: Vec<u8>,
        content_type: &str,
    ) -> reqwest::Result<Response> {
        self.maybe_refresh().await;
        self.inner
            .post(self.url(path))
            .bearer_auth(self.access_jwt())
            .header(reqwest::header::CONTENT_TYPE, content_type)
            .body(body)
            .send()
            .await
    }

    /// Exchange the refresh JWT for a fresh session via `com.atproto.server.refreshSession`.
    pub async fn refresh_session(&self) -> Result<(), BearerError> {
        let refresh_jwt = self.session.lock().unwrap().refresh_jwt.clone();
        let resp = self
            .inner
            .post(self.url("/xrpc/com.atproto.server.refreshSession"))
            .bearer_auth(refresh_jwt)
            .send()
            .await
            .map_err(|e| BearerError::Network(e.to_string()))?;
        if !resp.status().is_success() {
            return Err(BearerError::RefreshFailed(resp.status().as_u16()));
        }
        let body: RefreshResponse = resp
            .json()
            .await
            .map_err(|e| BearerError::Network(e.to_string()))?;
        let mut s = self.session.lock().unwrap();
        s.access_jwt = body.access_jwt;
        s.refresh_jwt = body.refresh_jwt;
        Ok(())
    }

    /// Refresh the session if the access token expires within the next 60 seconds.
    async fn maybe_refresh(&self) {
        // STUB (RED): no-op so the auto-refresh test fails first.
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use httpmock::prelude::*;

    fn session(access: &str) -> Arc<Mutex<BearerSession>> {
        Arc::new(Mutex::new(BearerSession {
            access_jwt: access.to_string(),
            refresh_jwt: "refresh".to_string(),
        }))
    }

    /// Build a syntactically-decodable JWT (`header.payload.sig`) whose payload carries `exp`.
    fn jwt_with_exp(exp: u64) -> String {
        let payload = serde_json::json!({ "exp": exp }).to_string();
        let b = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(payload);
        format!("h.{b}.s")
    }

    #[tokio::test]
    async fn get_attaches_bearer_authorization_header() {
        let server = MockServer::start();
        server.mock(|when, then| {
            when.method(GET)
                .path("/xrpc/com.atproto.server.checkAccountStatus")
                .header("Authorization", "Bearer dest_access_jwt");
            then.status(200)
                .json_body(serde_json::json!({ "activated": false }));
