    /// Unix `exp` from the access JWT payload, if it decodes. Unsigned, unverified — this
    /// is a self-held token; the value only gates the lazy-refresh decision.
    fn access_expiry(&self) -> Option<u64> {
        let token = self.session.lock().unwrap().access_jwt.clone();
        let payload_b64 = token.split('.').nth(1)?;
        let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .decode(payload_b64)
            .ok()?;
        let claims: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
        claims.get("exp")?.as_u64()
    }

    /// Refresh the session if the access token expires within the next 60 seconds.
    /// Best-effort: a refresh failure is logged and the (stale) token is used anyway so the
    /// server, not the client, is the authority on rejection.
    async fn maybe_refresh(&self) {
        let near_expiry = match self.access_expiry() {
            Some(exp) => {
                let now = SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);
                exp < now + 60
            }
            None => false,
        };
        if near_expiry {
            if let Err(e) = self.refresh_session().await {
                tracing::warn!(error = %e, "bearer session refresh failed; using stale token");
            }
        }
    }
}

