566	/// Build and locally sign the migration identity-leg operation.
567	///
568	/// Fetches the DID's audit log (for `prev` + current state), reads the destination
569	/// PDS's recommended credentials, assembles the proposed op (device key preserved at
570	/// rotationKeys[0]), runs the strict pre-sign guard, and signs with the per-DID device
571	/// key. `dest_client` is an already-authenticated client for the DESTINATION PDS,
572	/// supplied by the migration orchestrator.
573	pub async fn build_migration_op(
574	    pds_client: &PdsClient,
575	    dest_client: &OAuthClient,
576	    did: &str,
577	) -> Result<SignedMigrationOp, MigrateError> {
578	    let store = IdentityStore;
579	
580	    // 1. Per-DID device key.
581	    let device_pub =
582	        store
583	            .get_or_create_device_key(did)
584	            .map_err(|e| MigrateError::IdentityNotFound {
585	                message: format!("failed to get device key: {e}"),
586	            })?;
587	    let device_key_id = device_pub.key_id;
588	
589	    // 2. Current audit log -> prev + current state.
590	    let log_json =
591	        pds_client
592	            .fetch_audit_log(did)
593	            .await
594	            .map_err(|e| MigrateError::NetworkError {
595	                message: format!("failed to fetch audit log: {e}"),
596	            })?;
597	    let audit_log =
598	        crypto::parse_audit_log(&log_json).map_err(|e| MigrateError::InvalidAuditLog {
599	            message: format!("failed to parse audit log: {e}"),
600	        })?;
601	    let current = latest_op_state(&audit_log)?;
602	
603	    // 3. Destination-recommended credentials.
604	    let recommended = get_recommended_did_credentials(dest_client)
605	        .await
606	        .map_err(|e| MigrateError::NetworkError {
607	            message: format!("getRecommendedDidCredentials failed: {e}"),
608	        })?;
609	
610	    // 4. Assemble the proposed op (device key forced to rotationKeys[0]).
611	    //    The destination MUST recommend at least one rotation key (its reserved
612	    //    signing key) — otherwise the op would leave the new PDS unable to act.
613	    let recommended_rotation_keys = match recommended.rotation_keys.clone() {
614	        Some(keys) if !keys.is_empty() => keys,
615	        _ => {
616	            return Err(MigrateError::InvalidRecommendedCredentials {
617	                message: "destination recommended no rotation keys".to_string(),
618	            })
619	        }
620	    };
621	    let mut proposed_rotation_keys = vec![device_key_id.clone()];
622	    for key in &recommended_rotation_keys {
623	        if key != &device_key_id {
624	            proposed_rotation_keys.push(key.clone());
625	        }
626	    }
627	    let proposed_vms = recommended_verification_methods(&recommended)?;
628	    let proposed_services = recommended_services(&recommended)?;
629	    let proposed_endpoint = proposed_services
630	        .get(ATPROTO_PDS_SERVICE_ID)
631	        .map(|s| s.endpoint.clone())
632	        .expect("recommended_services guarantees atproto_pds is present");
633	    // A migration preserves the handle: keep current alsoKnownAs.
634	    let also_known_as = current.also_known_as.clone();
635	
636	    // 5. Strict pre-sign guard — the security gate.
637	    let inputs = MigrationInputs {
638	        device_key_id: device_key_id.clone(),
639	        current_rotation_keys: current.rotation_keys.clone(),
640	        current_also_known_as: current.also_known_as.clone(),
641	        recommended_rotation_keys: recommended_rotation_keys.clone(),
642	        proposed_rotation_keys: proposed_rotation_keys.clone(),
643	        proposed_also_known_as: also_known_as.clone(),
644	        proposed_service_ids: proposed_services.keys().cloned().collect(),
645	    };
646	    guard_migration_op(&inputs)?;
647	
648	    // 6. Sign locally with the per-DID device key.
649	    let sign_closure = crate::identity_store::per_did_sign_closure(did).map_err(|e| match e {
650	        PerDidSignError::DeviceKeyNotFound { message } => {
651	            MigrateError::IdentityNotFound { message }
652	        }
653	        PerDidSignError::SigningSetupFailed { message } => MigrateError::SigningFailed { message },
654	    })?;
655	    let signed = crypto::build_did_plc_rotation_op(
656	        &current.prev_cid,
657	        proposed_rotation_keys.clone(),
658	        proposed_vms,
659	        also_known_as,
660	        proposed_services,
661	        sign_closure,
662	    )
663	    .map_err(|e| MigrateError::SigningFailed {
664	        message: format!("failed to build rotation op: {e}"),
665	    })?;
666	
667	    // 7. Diff for review.
668	    let diff = build_migration_diff(&current, &proposed_rotation_keys, &proposed_endpoint);
669	
670	    Ok(SignedMigrationOp {
671	        diff,
672	        signed_op: serde_json::from_str(&signed.signed_op_json).map_err(|e| {
673	            MigrateError::SigningFailed {
674	                message: format!("failed to parse signed op JSON: {e}"),
675	            }
676	        })?,
677	    })
678	}
