806	    // Take (not clone) the signed op under the lock, so a concurrent or retried
807	    // submit cannot double-post the same non-idempotent PLC operation. The
808	    // destination client is left in place, so a failed submit can be rebuilt.
809	    let signed_op = {
810	        let mut migration = state.migration_state.lock().await;
811	        let ms = migration
812	            .as_mut()
813	            .ok_or_else(|| MigrateError::MigrationNotReady {
814	                message: "no pending migration to submit".to_string(),
815	            })?;
816	        if ms.did != did {
817	            return Err(MigrateError::MigrationNotReady {
818	                message: format!(
819	                    "migration state DID mismatch: expected {}, got {did}",
820	                    ms.did
821	                ),
822	            });
823	        }
824	        ms.signed_op
825	            .take()
826	            .ok_or_else(|| MigrateError::MigrationNotReady {
827	                message: "no signed op; build the migration operation first".to_string(),
828	            })?
