/// POST `com.atproto.server.activateAccount` on the DESTINATION (bearer), bringing the
/// migrated account live. The body must be empty — the server rejects any payload.
pub async fn activate_account(dest: &BearerClient) -> Result<(), MigrateError> {
    let resp = dest
        .post_empty("/xrpc/com.atproto.server.activateAccount")
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("activateAccount request failed: {e}"),
        })?;
    if resp.status().is_success() {
        Ok(())
    } else {
        let status = resp.status();
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        Err(MigrateError::PlcDirectoryError {
            message: format!("destination activateAccount rejected: {status}: {body}"),
        })
    }
}

/// POST `com.atproto.server.deactivateAccount` on the SOURCE (via its authenticated
/// `OAuthClient`), announcing the source is no longer the live host. Sends an empty JSON
/// object (no `deleteAfter`) — the source's repo stays readable so a mid-migration retry can
/// still pull blobs.
pub async fn deactivate_account(source: &OAuthClient) -> Result<(), MigrateError> {
    let resp = source
        .post(
            "/xrpc/com.atproto.server.deactivateAccount",
            &serde_json::json!({}),
        )
        .await
        .map_err(|e| MigrateError::NetworkError {
            message: format!("deactivateAccount request failed: {e}"),
        })?;
    if resp.status().is_success() {
        Ok(())
    } else {
        let status = resp.status();
        let body = resp
            .text()
            .await
            .unwrap_or_else(|_| "(response body unreadable)".to_string());
        Err(MigrateError::NetworkError {
            message: format!("source deactivateAccount returned {status}: {body}"),
        })
    }
}

