/// Finalize the migration for the DID parked in `MigrationState`: activate the destination
/// account, deactivate the source, then clear the state. Runs AFTER the identity leg has
/// repointed the DID (`submit_migration_op`), so the destination is already the DID's PDS of
/// record before it goes live. The testable core of `migration_finalize_cmd`.
///
/// Order matters: activate the destination first so the identity is always served somewhere,
/// then deactivate the source. Requires `dest_session` + `source_oauth_client`.
pub async fn migration_finalize_impl(
    app_state: &crate::oauth::AppState,
    did: String,
) -> Result<(), MigrateError> {
    let (source_oauth_client, dest_client) = {
        let migration = app_state.migration_state.lock().await;
        let ms = migration
            .as_ref()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "no pending migration to finalize".to_string(),
            })?;
        if ms.did != did {
            return Err(MigrateError::MigrationNotReady {
                message: format!(
                    "migration state DID mismatch: expected {}, got {did}",
                    ms.did
                ),
            });
        }
        let source_oauth_client =
            ms.source_oauth_client
                .clone()
                .ok_or_else(|| MigrateError::MigrationNotReady {
                    message: "source authentication missing; cannot deactivate the source"
                        .to_string(),
                })?;
        let dest_client = ms
            .dest_session
            .clone()
            .ok_or_else(|| MigrateError::MigrationNotReady {
                message: "destination session missing; cannot activate the destination"
                    .to_string(),
            })?;
        (source_oauth_client, dest_client)
    };

    activate_account(&dest_client).await?;
    deactivate_account(&source_oauth_client).await?;

    // Migration complete — clear the state.
    let mut migration = app_state.migration_state.lock().await;
    *migration = None;

    Ok(())
}

/// Tauri command: activate the destination, deactivate the source, and clear migration state.
#[tauri::command]
pub async fn migration_finalize_cmd(
    state: tauri::State<'_, crate::oauth::AppState>,
    did: String,
) -> Result<(), MigrateError> {
    migration_finalize_impl(&state, did).await
}

