/// A test source `OAuthClient` (access token `source-access`) targeting `base_url`.
fn source_oauth_client_for(base_url: String) -> crate::oauth_client::OAuthClient {
    use crate::oauth::{DPoPKeypair, OAuthSession};
    let keypair = DPoPKeypair::get_or_create().expect("dpop keypair");
    let session = Arc::new(std::sync::Mutex::new(OAuthSession {
        access_token: "source-access".to_string(),
        refresh_token: "source-refresh".to_string(),
        expires_at: u64::MAX,
        dpop_nonce: None,
    }));
    crate::oauth_client::OAuthClient::new_for_test(keypair, session, base_url)
}

/// A `MigrationState` with BOTH the source OAuth client and the destination bearer session
/// populated — the precondition the finalize leg requires.
fn migration_state_ready_for_finalize(
    did: &str,
    source_base: String,
    dest_base: String,
) -> MigrationState {
    MigrationState {
        did: did.to_string(),
        source_pds_url: source_base.clone(),
        dest_pds_url: dest_base.clone(),
        dest_service_did: Some("did:web:dest.example.com".to_string()),
        path: Some(MigrationPath::SelfSigned),
        source_oauth_client: Some(Arc::new(source_oauth_client_for(source_base))),
        dest_session: Some(Arc::new(dest_bearer_client(dest_base))),
        signed_op: None,
    }
}

