async fn migration_finalize_activates_dest_then_deactivates_source_and_clears_state() {
    let did = "did:plc:finalizeok";
    let dest = MockServer::start();
    let activate_mock = dest.mock(|when, then| {
        when.method(POST)
            .path("/xrpc/com.atproto.server.activateAccount")
            .header("Authorization", "Bearer dest-access");
        then.status(200);
    });
    let source = MockServer::start();
    let deactivate_mock = source.mock(|when, then| {
        when.method(POST)
            .path("/xrpc/com.atproto.server.deactivateAccount");
        then.status(200);
    });

    let app_state = crate::oauth::AppState::new();
    {
        let mut migration = app_state.migration_state.lock().await;
        *migration = Some(migration_state_ready_for_finalize(
            did,
            source.base_url(),
            dest.base_url(),
        ));
    }

    migration_finalize_impl(&app_state, did.to_string())
        .await
        .expect("finalize succeeds");

    activate_mock.assert();
    deactivate_mock.assert();
    assert!(
        app_state.migration_state.lock().await.is_none(),
        "MigrationState must be cleared after a successful finalize"
    );
}

