/**
 * Prompt for biometric authentication (Face ID / Touch ID) via `@tauri-apps/plugin-biometric`.
 * Gates the PLC-op submission in the migration review screen — the user is the signer, so this
 * is the authorization boundary, not decorative confirmation.
 *
 * The plugin exists only on iOS/Android, so it is imported dynamically: on the desktop/host
 * build (no plugin) or a simulator without enrolled biometrics (no hardware) it RESOLVES —
 * there is nothing to gate against, and blocking the migration there would be wrong. It REJECTS
 * only on a genuine denial (the user cancelled or failed the prompt), which the caller treats as
 * "do not submit". `allowDeviceCredential` lets a device without enrolled biometrics fall back to
 * the passcode, so a configured device is always genuinely gated.
 */
export const authenticateBiometric = async (reason: string): Promise<void> => {
  let plugin: typeof import('@tauri-apps/plugin-biometric');
  try {
    plugin = await import('@tauri-apps/plugin-biometric');
  } catch {
    return; // plugin absent (desktop dev / host build) — nothing to gate.
  }
  let available: boolean;
  try {
    available = (await plugin.checkStatus()).isAvailable;
  } catch {
    return; // status unreadable — treat as unavailable rather than blocking.
  }
  if (!available) return; // no enrolled hardware (e.g. a bare simulator).
  await plugin.authenticate(reason, { allowDeviceCredential: true });
};

